package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamEconomyDevBank1 {
  private const val T = "ආර්ථික ක්‍රම, සුබසාධනය, බහුසංස්කෘතික සමාජය හා තිරසාර සංවර්ධනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("මිනිසාගේ අසීමිත අවශ්‍යතා සහ සීමිත සම්පත් අතර පවතින පරතරය නිසා හටගන්නා මූලික ආර්ථික ගැටලුව කුමක්ද?", "හිඟකම (Scarcity)", "උද්ධමනය", "ජාත්‍යන්තර වෙළඳාම", "රාජ්‍ය විගණනය", "සම්පත් සීමිත වීම හේතුවෙන් කුමක්, කෙසේ, කවුරුන් සඳහා නිපදවන්නේද යන්න තීරණය කිරීමට සිදුවේ."),
    q("පෞද්ගලික දේපළ අයිතිය, නිදහස් ව්‍යවසාය සහ ලාභය උපරිම කිරීම මත පදනම් වූ ආර්ථික ක්‍රමය කුමක්ද?", "ධනවාදී (වෙළඳපොළ) ආර්ථික ක්‍රමය", "සමාජවාදී ආර්ථික ක්‍රමය", "සාම්ප්‍රදායික ආර්ථික ක්‍රමය", "වැඩවසම් ආර්ථික ක්‍රමය", "නිෂ්පාදන සම්පත් පෞද්ගලික අංශය සතු වී මිල යාන්ත්‍රණය මඟින් ක්‍රියාත්මක වන ක්‍රමය ධනවාදී ආර්ථිකයයි."),
    q("ධනවාදී ආර්ථික ක්‍රමයක නිෂ්පාදන හා බෙදාහැරීමේ තීරණ ප්‍රධාන වශයෙන් මෙහෙයවනු ලබන්නේ කුමක් මඟින්ද?", "ඉල්ලුම හා සැපයුම මත රඳා පවතින මිල යාන්ත්‍රණය", "මධ්‍යම රජයේ සැලසුම් කොමිසම", "පළාත් සභා ආණ්ඩුකාරවරයා", "සමථ මණ්ඩල තීරණ", "රජයේ මැදිහත්වීම අවම වී වෙළඳපොළ ඉල්ලුම හා සැපයුම අනුව මිල තීරණය වේ."),
    q("ධනවාදී ආර්ථික විද්‍යාවේ පියා ලෙස සැලකෙන 'ජාතීන්ගේ ධනය' (Wealth of Nations) කෘතිය රචනා කළ විද්වතා කවුද?", "ඇඩම් ස්මිත් (Adam Smith)", "කාල් මාක්ස්", "ජෝන් මේනාඩ් කේන්ස්", "ඒ.වී. ඩයිසි", "1776 දී ඇඩම් ස්මිත් නිදහස් වෙළඳපොළ හා 'අදෘශ්‍යමාන හස්තය' පිළිබඳ සංකල්ප ඉදිරිපත් කළේය."),
    q("සියලු ප්‍රධාන නිෂ්පාදන සම්පත් රජය සතු වී මධ්‍යම සැලසුම් ක්‍රමයක් යටතේ ක්‍රියාත්මක වන ආර්ථික ක්‍රමය කුමක්ද?", "සමාජවාදී ආර්ථික ක්‍රමය", "ධනවාදී ආර්ථික ක්‍රමය", "විවෘත වෙළඳපොළ ආර්ථික ක්‍රමය", "පෞද්ගලික ඒකාධිකාරය", "පුද්ගලික ලාභය වෙනුවට සමාජ සුබසාධනය හා සමානාත්මතාව අරමුණු කරගෙන රජය නිෂ්පාදනය මෙහෙයවයි."),
    q("රාජ්‍ය අංශය සහ පෞද්ගලික අංශය යන දෙකම සමගාමීව ක්‍රියාත්මක වන වත්මන් ශ්‍රී ලංකාවේ ආර්ථික ක්‍රමය කුමක්ද?", "මිශ්‍ර ආර්ථික ක්‍රමය", "සම්පූර්ණ විධාන ආර්ථික ක්‍රමය", "ශුද්ධ ධනවාදී ක්‍රමය", "භාණ්ඩ හුවමාරු ක්‍රමය", "පෞද්ගලික ව්‍යවසායන්ට ඉඩ දෙන අතරම අධ්‍යාපන, සෞඛ්‍ය හා උපයෝගිතා සේවා රජය මඟින් පවත්වාගෙන යයි."),
    q("ධනවාදී ආර්ථික ක්‍රමයේ ප්‍රධාන දුර්වලතාවක් ලෙස ආර්ථික විද්‍යාඥයන් පෙන්වා දෙන්නේ කුමක්ද?", "ධනවතුන් හා දුප්පතුන් අතර ආදායම් විෂමතාව වැඩි වීම", "තාක්ෂණික නවෝත්පාදන සම්පූර්ණයෙන් නැතිවීම", "පාරිභෝගික භාණ්ඩ තේරීම සීමා වීම", "පෞද්ගලික ව්‍යවසාය තහනම් වීම", "ලාභය පමණක් මුල් කර ගැනීම නිසා පොදු සුබසාධනය අඩු වී ආදායම් පරතරය පුළුල් විය හැක."),
    q("සමාජවාදී ආර්ථික ක්‍රමයේ ප්‍රධාන දුර්වලතාවක් ලෙස සැලකෙන්නේ පහත සඳහන් කුමක්ද?", "පුද්ගලික දිරිගැන්වීම හා තරගකාරී කාර්යක්ෂමතාව අඩු වීම", "අධික පෞද්ගලික ඒකාධිකාර බිහිවීම", "සියලුම පාසල් පෞද්ගලීකරණය වීම", "මධ්‍යම සැලසුම් නොමැති වීම", "පෞද්ගලික ලාභ අපේක්ෂාව නොමැති වීමෙන් නවෝත්පාදන උනන්දුව හා ඵලදායීතාව පහත වැටිය හැක."),
    q("ශ්‍රී ලංකාව ආනයන සීමා ඉවත් කර 'විවෘත ආර්ථික ප්‍රතිපත්තිය' ප්‍රථම වරට හඳුන්වා දුන්නේ කුමන වර්ෂයේදීද?", "1977", "1948", "1956", "1972", "1977 නොවැම්බර් අයවැයෙන් වෙළඳපොළ ආර්ථික ලිහිල්කරණය හා නිදහස් වෙළඳ කලාප හඳුන්වා දුනි."),
    q("විවෘත ආර්ථික ක්‍රමය හඳුන්වා දීමෙන් පසු ශ්‍රී ලංකාවේ අපනයන ආදායම හා රැකියා නියුක්තිය ඉහළ නැංවීමට පිහිටුවූයේ මොනවාද?", "නිදහස් වෙළඳ කලාප (ආයෝජන ප්‍රවර්ධන කලාප)", "සමථ මණ්ඩල", "රාජ්‍ය මන්ත්‍රණ සභා", "ග්‍රාමීය අධිකරණ", "1978 දී කටුනායක හා පසුව බියගම වැනි ආයෝජන ප්‍රවර්ධන කලාප මඟින් විදේශ ආයෝජන ගෙන්වා ගැනිණි."),
    q("සෑම පුරවැසියෙකුගේම මූලික අවශ්‍යතා සපුරා ආරක්ෂාව සැලසීම රජයේ වගකීමක් ලෙස සලකන රාජ්‍ය ආකෘතිය කුමක්ද?", "සුබසාධක රාජ්‍යය (Welfare State)", "පොලිස් රාජ්‍යය", "රදළ රාජ්‍යය", "මිලිටරි රාජ්‍යය", "නිදහස් අධ්‍යාපනය, සෞඛ්‍යය, විශ්‍රාම වැටුප් හා සහනාධාර සපයන රජය සුබසාධක රාජ්‍යයක් වේ."),
    q("1945 ඔක්තෝබර් 01 දින ශ්‍රී ලංකාවේ 'නිදහස් අධ්‍යාපන ක්‍රමය' හඳුන්වා දීමට පුරෝගාමී වූ අධ්‍යාපන අමාත්‍යවරයා කවුද?", "ආචාර්ය සී.ඩබ්ලිව්.ඩබ්ලිව්. කන්නන්ගර මහතා", "ඩී.ඇස්. සේනානායක මහතා", "ඇන්.ඇම්. පෙරේරා මහතා", "ටී.බී. ජයා මහතා", "බාලාංශයේ සිට විශ්වවිද්‍යාලය දක්වා නොමිලේ අධ්‍යාපනය ලබාදීමට කන්නන්ගර මැතිතුමා කටයුතු කළේය."),
    q("නිදහස් අධ්‍යාපන ප්‍රතිපත්තිය සමඟ සිසුන්ගේ පෝෂණය හා පාසල් පැමිණීම වැඩි කිරීමට ක්‍රියාත්මක වන රාජ්‍ය සුබසාධන වැඩසටහන් මොනවාද?", "නොමිලේ පෙළපොත්, නිල ඇඳුම් රෙදි හා පාසල් දිවා ආහාරය", "පාසල් ගාස්තු අය කිරීම", "ප්‍රාථමික පාසල් වැසීම", "විභාග ගාස්තු දස ගුණයකින් වැඩි කිරීම", "දුප්පත් පොහොසත් භේදයකින් තොරව සැමට අධ්‍යාපන සමානාත්මතාව රැකීමට මෙම සුබසාධන සේවා ක්‍රියාත්මක වේ."),
    q("ආර්ථික දුෂ්කරතා ඇති විශ්වවිද්‍යාල සිසුන්ට උසස් අධ්‍යාපනය සඳහා 1981 දී 'මහපොළ ශිෂ්‍යත්ව අරමුදල' ආරම්භ කළේ කවුද?", "ලලිත් ඇතුලත්මුදලි මහතා", "ආචාර්ය සී.ඩබ්ලිව්.ඩබ්ලිව්. කන්නන්ගර මහතා", "හෙක්ටර් කොබ්බෑකඩුව මහතා", "ෆීලික්ස් ඩයස් බණ්ඩාරනායක මහතා", "වෙළඳ හා නාවික අමාත්‍යවරයාව සිටි ලලිත් ඇතුලත්මුදලි මහතා මහපොළ ශිෂ්‍යත්ව ක්‍රමය බිහි කළේය."),
    q("ශ්‍රී ලංකාවේ දරිද්‍රතාවයෙන් පෙළෙන පවුල්වලට සෘජු මූල්‍ය ආධාර ලබාදීම සඳහා වර්තමානයේ ක්‍රියාත්මක සමාජ ආරක්ෂණ වැඩසටහන කුමක්ද?", "අස්වැසුම සුබසාධන ප්‍රතිලාභ වැඩසටහන", "සී.ඩබ්ලිව්.ඩබ්ලිව්. ශිෂ්‍යත්වය", "සුරකිමු ගංගා ව්‍යාපෘතිය", "ගම්උදාව වැඩසටහන", "සමෘද්ධි හා ජනසවිය වෙනුවට අඩු ආදායම්ලාභී පවුල් ඉලක්ක කර අස්වැසුම සුබසාධන යෝජනා ක්‍රමය ඇරඹුණි."),
    q("රජය විසින් සුබසාධන සේවා සහ පොදු යටිතල පහසුකම් සඳහා අරමුදල් රැස් කරන ප්‍රධානතම ආදායම් මාර්ගය කුමක්ද?", "බදු ආදායම් (සෘජු හා වක්‍ර බදු)", "විදේශීය ත්‍යාග පමණක්", "මුදල් නෝට්ටු නොනවත්වා මුද්‍රණය කිරීම", "ලොතරැයි පත් පමණක්", "ආදායම් බදු, වැට් බදු හා රේගු බදු රාජ්‍ය අයවැයේ ප්‍රධාන ආදායම් ප්‍රභවයන් වේ."),
    q("පුද්ගලයෙකුගේ හෝ සමාගමක ආදායම මත සෘජුවම අය කරන අතර වෙනත් අයෙකුට පැවරිය නොහැකි බද්ද කුමක්ද?", "සෘජු බදු (පුද්ගල ආදායම් බද්ද වැනි)", "වක්‍ර බදු (VAT බද්ද වැනි)", "රේගු ආනයන බද්ද", "සුරාබදු", "ආදායම් බදු හා සංගත බදු (Corporate Tax) බදු ගෙවන්නා විසින්ම සෘජුව ගෙවිය යුතුය."),
    q("භාණ්ඩ හා සේවා මිලදී ගැනීමේදී පාරිභෝගිකයා විසින් මිලට එකතු කර ගෙවනු ලබන බදු වර්ගය කුමක්ද?", "වක්‍ර බදු (Indirect Taxes)", "සෘජු බදු", "වරිපනම් බදු", "ප්‍රාග්ධන බදු", "එකතු කළ අගය මත බද්ද (VAT), රේගු බදු හා සුරාබදු භාණ්ඩ මිල හරහා පාරිභෝගිකයා මත පැටවේ."),
    q("ආදායම් මට්ටම ඉහළ යන විට බදු අනුපාතයද වැඩිවන සාධාරණ බදු ක්‍රමය හඳුන්වන්නේ කුමන නමින්ද?", "ප්‍රගතිශීලී බදු ක්‍රමය (Progressive Tax)", "ප්‍රතිගාමී බදු ක්‍රමය (Regressive Tax)", "සමානුපාතික බදු ක්‍රමය", "විනෝද බද්ද", "ධනවතුන්ගෙන් වැඩි ප්‍රතිශතයකුත් අඩු ආදායම්ලාභීන්ට බදු සහනත් දීමෙන් ආදායම් විෂමතාව අඩු කෙරේ."),
    q("ධනවතුන්ට හා දුප්පතුන්ට දෙදෙනාටම එකම ප්‍රතිශතයකින් අත්‍යවශ්‍ය භාණ්ඩ මත පනවන වක්‍ර බදු සාමාන්‍යයෙන් කවර ස්වභාවයක් ගනීද?", "ප්‍රතිගාමී බදු ස්වභාවය (දුප්පතුන්ගේ ආදායමෙන් වැඩි පංගුවක් වැය වේ)", "ප්‍රගතිශීලී ස්වභාවය", "සෘජු ආදායම් බදු ස්වභාවය", "රාජ්‍ය මුක්ති ස්වභාවය", "ආහාර හා ඉන්ධන වැනි භාණ්ඩ මත පනවන වක්‍ර බදු අඩු ආදායම්ලාභීන්ට වැඩි ආර්ථික බරක් ඇති කරයි."),
    q("1962 දී ඇමරිකානු ජනාධිපති ජෝන් එෆ්. කෙනඩි ප්‍රථම වරට ප්‍රකාශයට පත් කළ මූලික පාරිභෝගික අයිතිවාසිකම් හතරට අයත් වන්නේ මොනවාද?", "ආරක්ෂාව, තොරතුරු දැනගැනීම, තේරීම සහ සවන් දීම (නියෝජනය)", "ණය ගැනීම, බදු නොගෙවීම, වෙළඳාම සහ ආනයනය", "ඡන්දය, පෙළපාලිය, අධිකරණය සහ බදු", "නිෂ්පාදනය, ප්‍රචාරණය, ප්‍රවාහනය සහ ලාභය", "සෑම වසරකම මාර්තු 15 ලෝක පාරිභෝගික දිනය සමරන්නේ මෙම අයිතිවාසිකම් සිහිපත් කිරීමටය."),
    q("ශ්‍රී ලංකාවේ පාරිභෝගිකයන් වෙළඳ වංචාවලින් හා අධික මිල ගණන්වලින් ආරක්ෂා කිරීම සඳහා පනවා ඇති ප්‍රධාන නීතිය කුමක්ද?", "2003 අංක 09 දරන පාරිභෝගික කටයුතු පිළිබඳ අධිකාරි පනත", "1987 අංක 15 ප්‍රාදේශීය සභා පනත", "2016 අංක 12 තොරතුරු පනත", "1996 අංක 21 මානව හිමිකම් පනත", "ව්‍යාජ වෙළඳ ප්‍රචාරණ, කල් ඉකුත් වූ භාණ්ඩ හා උපරිම සිල්ලර මිල කඩ කිරීම මෙම පනතෙන් තහනම් කර ඇත."),
    q("වෙළඳපොළෙන් භාණ්ඩයක් මිලදී ගැනීමේදී පාරිභෝගිකයා පරීක්ෂා කළ යුතු ප්‍රධානතම ලේබල් තොරතුරු මොනවාද?", "නිෂ්පාදිත දිනය, කල් ඉකුත් වන දිනය, අමුද්‍රව්‍ය, බර සහ උපරිම සිල්ලර මිල", "වෙළෙන්දාගේ ජාතික හැඳුනුම්පත් අංකය", "වෙළඳසැලේ විදුලි බිල්පත", "ආනයනික රේගු නිලධාරියාගේ නම", "නිවැරදි තොරතුරු දැනගැනීමේ අයිතිය අනුව නිෂ්පාදන ඇසුරුමේ මෙම තොරතුරු සිංහල, දෙමළ හා ඉංග්‍රීසි බසින් තිබිය යුතුය."),
    q("ශ්‍රී ලංකාවේ භාණ්ඩ හා සේවාවල ජාතික ප්‍රමිතිය හා ගුණාත්මක බව සහතික කිරීමට නිකුත් කරන ලාංඡනය කුමක්ද?", "SLS ප්‍රමිති සහතිකය", "ISO 9001 පමණක්", "UNESCO ලාංඡනය", "PAFFREL මුද්‍රාව", "ශ්‍රී ලංකා ප්‍රමිති ආයතනය (SLSI) ආහාර හා කාර්මික භාණ්ඩවල ආරක්ෂාව සඳහා SLS ප්‍රමිතිය පිරිනමයි."),
    q("කිසියම් වෙළෙන්දෙකු කෘත්‍රිම හිඟයක් මවා පෑම සඳහා අත්‍යවශ්‍ය ආහාර ද්‍රව්‍ය සඟවා තබාගැනීම හඳුන්වන්නේ කුමන වරදක් ලෙසද?", "භාණ්ඩ සඟවා තැබීම හෙවත් කළුකඩ වෙළඳාම (Hoarding)", "නිදහස් තරගකාරිත්වය", "පාරිභෝගික සුබසාධනය", "සමුපකාර ව්‍යාපාරය", "මිල ඉහළ යන තුරු භාණ්ඩ සඟවා තැබීම පාරිභෝගික කටයුතු අධිකාරි පනත යටතේ දඬුවම් ලැබිය හැකි වරදකි."),
    q("සෑම ගමකම ජනතාව එක්වී සාධාරණ මිලට භාණ්ඩ බෙදාහැරීමට හා ඉතුරුම් සඳහා පිහිටුවා ගන්නා ප්‍රජා ආර්ථික සංවිධාන කුමක්ද?", "සමුපකාර සමිති (Cooperative Societies)", "ව්‍යාපාරික ඒකාධිකාර", "කොටස් වෙළඳපොළ සමාගම්", "විදේශීය බැංකු", "ලෝච්ඩේල් පුරෝගාමීන් 1844 දී ඇරඹූ සමුපකාර ව්‍යාපාරය ප්‍රජාතන්ත්‍රවාදී අයිතිය හා සාධාරණ වෙළඳාම මත පදනම් වේ."),
    q("විවිධ ජනවර්ග, ආගම්, භාෂා හා සංස්කෘතීන්ට අයත් ජනතාව එකම රාජ්‍යයක් තුළ සහජීවනයෙන් ජීවත් වන සමාජය කුමක්ද?", "බහුසංස්කෘතික සමාජය (Multicultural Society)", "ඒකසංස්කෘතික සමාජය", "ගෝත්‍රික සමාජය", "සංවෘත සමාජය", "සිංහල, දෙමළ, මුස්ලිම්, බර්ගර් හා මැලේ ආදී විවිධ ජන කොටස් වෙසෙන ශ්‍රී ලංකාව බහුසංස්කෘතික සමාජයකි."),
    q("'විවිධත්වය තුළින් ඒකීයත්වය' (Unity in Diversity) යන සංකල්පයෙන් ශ්‍රී ලංකාව වැනි රටකට ලැබෙන පණිවිඩය කුමක්ද?", "සියලු ජාති හා ආගමික අනන්‍යතා රැකගනිමින් එක් ශ්‍රී ලාංකික ජාතියක් ලෙස සමගියෙන් ක්‍රියා කිරීම", "සියලු සුළු සංස්කෘතීන් අහෝසි කර එක් භාෂාවක් පමණක් භාවිත කිරීම", "ජන කොටස් වෙන වෙනම කඳවුරුවල වෙන් කර තැබීම", "ආගමික උත්සව තහනම් කිරීම", "විවිධත්වය බෙදීමට හේතුවක් නොව ජාතික ශක්තියක් හා සංස්කෘතික පොහොසත්කමක් ලෙස සැලකීම මෙහි හරයයි."),
    q("බහුසංස්කෘතික සමාජයක ජාතික සංහිඳියාව ගොඩනැගීමට ඇති ප්‍රධානතම බාධකය වන්නේ කුමක්ද?", "ජාතිවාදය, ආගමික අන්තවාදය හා අනෙකා කෙරෙහි ඇති සැකය", "විවිධ සංස්කෘතික උත්සව සැමරීම", "ද්විභාෂා ඉගෙනීම", "අන්තර් සංස්කෘතික ක්‍රීඩා උළෙල", "වෙනස්කම් ගරු නොකර තම කණ්ඩායම පමණක් උසස් යැයි සිතීම සමාජ ගැටුම්වලට මුල් වේ."),
    q("ශ්‍රී ලංකාවේ සියලුම පාසල්වල දෙවන ජාතික භාෂාව (සිංහල/දෙමළ) ඉගැන්වීමෙන් අපේක්ෂා කරන සමාජීය අරමුණ කුමක්ද?", "විවිධ භාෂා කතා කරන ජන කොටස් අතර අන්‍යෝන්‍ය අවබෝධය හා සුහදතාව වැඩි කිරීම", "ඉංග්‍රීසි භාෂාව තහනම් කිරීම", "විභාග අපහසු කිරීම", "පාසල් කාලය දීර්ඝ කිරීම", "එකිනෙකාගේ භාෂාව තේරුම් ගැනීම ජාතික ඒකාග්‍රතාව හා සංහිඳියාව ශක්තිමත් කරයි."),
    q("පහත සඳහන් උත්සව අතරින් ශ්‍රී ලංකාවේ බහුසංස්කෘතික උරුමය මනාව පිළිබිඹු කරන ආගමික හා සංස්කෘතික අංග මොනවාද?", "වෙසක්, තෛපොංගල්, රාමසාන් සහ නත්තල් උත්සව", "රාජ්‍ය අයවැය විවාද පමණක්", "පළාත් පාලන මැතිවරණ", "රේගු වෙන්දේසි", "සියලු ප්‍රධාන ආගම්වල උත්සව ජාතික නිවාඩු දින ලෙස පිළිගෙන සැමරීම රටේ සංස්කෘතික ගෞරවය පෙන්වයි."),
    q("ජාතික ආදායම වැඩි කර ගැනීමේදී පරිසරයට හා සමාජ සාධාරණත්වයට හානි නොකරන 'තිරසාර සංවර්ධනය' (Sustainable Development) නිර්වචනය කළේ කුමන වාර්තාවෙන්ද?", "1987 බෲන්ඩ්ට්ලන්ඩ් වාර්තාව (Our Common Future)", "1948 මානව හිමිකම් ප්‍රකාශනය", "1931 ඩොනමෝර් වාර්තාව", "1945 කන්නන්ගර වාර්තාව", "අනාගත පරපුරේ අවශ්‍යතා ඉටු කිරීමේ හැකියාවට හානි නොකර වත්මන් අවශ්‍යතා සපුරාලීම ඉන් අර්ථ දැක්විණි."),
    q("තිරසාර සංවර්ධනයක ප්‍රධාන කුළුණු තුන (Three Pillars) ලෙස සැලකෙන්නේ මොනවාද?", "ආර්ථික වර්ධනය, සමාජ සමානාත්මතාව සහ පාරිසරික සංරක්ෂණය", "යුද බලය, බදු අය කිරීම සහ වෙළඳ ඒකාධිකාරය", "කර්මාන්තශාලා, ගුවන්තොටුපළ සහ වරාය", "දේශපාලන පක්ෂ, මැතිවරණ සහ සභා", "පරිසරය හා මිනිසා ආරක්ෂා කරමින් ආර්ථික දියුණුව ලබාගැනීම මෙම කුළුණු තුනේ සමබරතාව මත රැඳේ."),
    q("එක්සත් ජාතීන්ගේ සංවිධානය 2030 වර්ෂය ඉලක්ක කරගෙන හඳුන්වා දී ඇති තිරසාර සංවර්ධන ඉලක්ක (SDGs) සංඛ්‍යාව කීයද?", "ඉලක්ක 17", "ඉලක්ක 8", "ඉලක්ක 10", "ඉලක්ක 30", "දිළිඳුකම තුරන් කිරීම, ගුණාත්මක අධ්‍යාපනය හා දේශගුණික ක්‍රියාමාර්ග ඇතුළු SDGs 17ක් 2015 දී සම්මත විය."),
    q("ශ්‍රී ලංකාවේ නව කර්මාන්තශාලාවක් හෝ මහාමාර්ග ව්‍යාපෘතියක් ආරම්භ කිරීමට පෙර අනිවාර්යයෙන් සිදු කළ යුතු පාරිසරික පරීක්ෂාව කුමක්ද?", "පාරිසරික බලපෑම් ඇගයීම (EIA)", "මැතිවරණ සීමා නිර්ණය", "වරිපනම් තක්සේරුව", "තැපැල් ඡන්ද ගණනය", "1980 අංක 47 ජාතික පාරිසරික පනත යටතේ මධ්‍යම පරිසර අධිකාරියේ (CEA) EIA අනුමැතිය අනිවාර්ය වේ."),
    q("ශ්‍රී ලංකාවේ පාරිසරික නීති ක්‍රියාත්මක කිරීම හා පරිසර ආරක්ෂණ බලපත්‍ර (EPL) නිකුත් කිරීම සිදුකරන ප්‍රධාන ආයතනය කුමක්ද?", "මධ්‍යම පරිසර අධිකාරිය (CEA)", "පාරිභෝගික කටයුතු අධිකාරිය", "නාගරික සංවර්ධන අධිකාරිය", "ජාතික ළමා ආරක්ෂක අධිකාරිය", "පරිසර දූෂණය වැළැක්වීම හා කර්මාන්ත නියාමනය මධ්‍යම පරිසර අධිකාරිය මඟින් කෙරේ."),
    q("පරිසර සංරක්ෂණයේදී හා අපද්‍රව්‍ය අවම කිරීමේදී යොදාගන්නා '3R සංකල්පය' මඟින් දැක්වෙන්නේ කුමක්ද?", "අවම කිරීම (Reduce), නැවත භාවිතය (Reuse) සහ ප්‍රතිචක්‍රීකරණය (Recycle)", "කැපීම, පිළිස්සීම සහ වැළලීම", "ආනයනය, විකිණීම සහ බැහැර කිරීම", "ගබඩා කිරීම, සැඟවීම සහ ඉවත් කිරීම", "සම්පත් නාස්තිය හා කසළ ප්‍රමාණය අඩු කර පරිසරය රැකගැනීමට 3R ක්‍රමවේදය අනුගමනය කෙරේ."),
    q("ගෝලීය උණුසුම ඉහළ යාම හා දේශගුණික විපර්යාස අවම කිරීම සඳහා හරිතාගාර වායු විමෝචනය පාලනය කිරීමේ 2015 ජාත්‍යන්තර ගිවිසුම කුමක්ද?", "පැරිස් දේශගුණික ගිවිසුම (Paris Agreement)", "මැග්නා කාර්ටා ගිවිසුම", "ජිනීවා යුද සම්මුතිය", "සාර්ක් වෙළඳ ගිවිසුම", "ගෝලීය උෂ්ණත්වය ඉහළ යාම සෙල්සියස් අංශක 1.5–2ට සීමා කිරීමට ලෝක රටවල් පැරිස් ගිවිසුමට එළඹුණි."),
    q("ශ්‍රී ලංකාව වැනි නිවර්තන රටවල 'සුළං, සූර්ය හා ජල විදුලි බලය' ප්‍රවර්ධනය කිරීම වැදගත් වන්නේ ඇයි?", "පුනර්ජනනීය බලශක්ති ප්‍රභවයන් නිසා පරිසර දූෂණය හා ඉන්ධන ආනයන වියදම අඩු වන බැවිනි", "ඒවා ඛනිජ තෙල්වලට වඩා විෂ වායු පිට කරන බැවිනි", "වනාන්තර කපා දැමීමට හැකි නිසාය", "කර්මාන්තශාලා වසා දැමීමට හැකි නිසාය", "පොසිල ඉන්ධන මත යැපීම අඩු කර පිරිසිදු බලශක්තියට මාරු වීම SDG 7 වන ඉලක්කයයි."),
    q("වනජීවීන් හා වනාන්තර ආරක්ෂා කිරීම සඳහා ශ්‍රී ලංකාවේ පවතින ප්‍රධාන පරිසර උරුම ප්‍රදේශයක් ලෙස යුනෙස්කෝ ලෝක උරුමයක් බවට පත් කර ඇත්තේ කුමක්ද?", "සිංහරාජ වනාන්තරය හා මධ්‍යම කඳුකරය", "කටුනායක වෙළඳ කලාපය", "කොළඹ වරාය නගරය", "පේරාදෙණිය දුම්රිය ස්ථානය", "සිංහරාජ වැසි වනාන්තරය ජෛව විවිධත්වය අතින් අතිශය වැදගත් යුනෙස්කෝ ස්වභාවික ලෝක උරුමයකි."),
    q("ගංවතුර, නායයෑම් හා සුනාමි වැනි ස්වභාවික ආපදා අවදානම් අවම කර ගැනීමට ශ්‍රී ලංකාවේ පිහිටුවා ඇති ජාතික ආයතනය කුමක්ද?", "ආපදා කළමනාකරණ මධ්‍යස්ථානය (DMC)", "විගණකාධිපති දෙපාර්තමේන්තුව", "මැතිවරණ කොමිෂන් සභාව", "පාරිභෝගික අධිකාරිය", "2005 අංක 13 ආපදා කළමනාකරණ පනත යටතේ පූර්ව අනතුරු ඇඟවීම හා ආපදා කළමනාකරණය මෙම මධ්‍යස්ථානයෙන් කෙරේ."),
    q("නිෂ්පාදන ආර්ථිකයක 'පෞද්ගලික අංශයට' රාජ්‍ය සේවාවන්ට වඩා වැඩි කාර්යක්ෂමතාවක් බොහෝ විට තිබීමට හේතුව කුමක්ද?", "වෙළඳපොළ තරගකාරිත්වය සහ ලාභ අරමුණ මත වියදම් පාලනය කිරීම", "නීති රීතිවලින් සම්පූර්ණයෙන් නිදහස් වීම", "මහජන බදු මුදල් අසීමිතව ලැබීම", "පාරිභෝගිකයන් නොසලකා හැරීම", "තරගකාරී වෙළඳපොළේ රැඳී සිටීමට පෞද්ගලික ආයතන කාර්යක්ෂමතාව හා පාරිභෝගික සේවය වැඩි කරයි."),
    q("රටේ සංවර්ධනය මැනීමේදී දළ දේශීය නිෂ්පාදිතයට (GDP) අමතරව 'මානව සංවර්ධන දර්ශකය' (HDI) යොදාගැනීම වැදගත් වන්නේ ඇයි?", "ආදායමට අමතරව අධ්‍යාපනය හා සෞඛ්‍ය (ආයු අපේක්ෂාව) තත්ත්වයද එයින් මනින බැවිනි", "එයින් කර්මාන්තශාලා සංඛ්‍යාව පමණක් ගණන් කරන බැවිනි", "එය හමුදා ශක්තිය පමණක් මනින බැවිනි", "එයින් වාර්ෂික වර්ෂාපතනය මනින බැවිනි", "මිනිසුන්ගේ ජීවන තත්ත්වය හා අධ්‍යාපන/සෞඛ්‍ය මට්ටම ඇතුළත් සැබෑ මානව ප්‍රගතිය HDI මඟින් පෙන්වයි."),
    q("ශ්‍රී ලංකාවේ ආර්ථිකයට ඉහළ විදේශ විනිමය ආදායමක් ගෙන එන ප්‍රධාන ක්ෂේත්‍ර තුනක් කවරේද?", "ඇඟලුම් අපනයනය, විදේශ ශ්‍රමික ප්‍රේෂණ, තේ සහ සංචාරක ව්‍යාපාරය", "ඛනිජ තෙල් අපනයනය සහ මෝටර් රථ නිෂ්පාදනය", "ගල් අඟුරු අපනයනය සහ ගුවන් යානා නිෂ්පාදනය", "යකඩ අපනයනය සහ න්‍යෂ්ටික බලශක්තිය", "ශ්‍රී ලංකාවේ විදේශ විනිමය උපයන ප්‍රමුඛ අංශ ලෙස විදේශ ප්‍රේෂණ, සංචාරක, ඇඟලුම් හා වැවිලි බෝග පවතී."),
    q("පාරිභෝගිකයෙකු වශයෙන් සුපිරි වෙළඳසැලකින් භාණ්ඩ මිලදී ගැනීමේදී 'ලදුපතක් (Bill/Receipt)' ලබාගැනීම වැදගත් වන්නේ ඇයි?", "භාණ්ඩයේ දෝෂයක් හෝ වැඩි මිල අය කිරීමක් ඇති විට පැමිණිලි කිරීමට නීතිමය සාක්ෂියක් වන බැවිනි", "වෙළඳසැලේ ලාභය වැඩි කිරීමට", "රේගු බදු නිදහස් කර ගැනීමට", "භාණ්ඩය නැවත විකිණීමට", "පාරිභෝගික කටයුතු අධිකාරියට පැමිණිලි කිරීමේදී මිලදී ගැනීම තහවුරු කිරීමට බිල්පත අත්‍යවශ්‍ය වේ."),
    q("වෙළඳපොළේ පාරිභෝගිකයන් නොමඟ යවන 'අසත්‍ය වෙළඳ දැන්වීම්' (Misleading Advertisements) නියාමනය කිරීමෙන් සුරැකෙන්නේ කුමන අයිතියද?", "සත්‍ය තොරතුරු දැනගැනීමේ හා තෝරාගැනීමේ පාරිභෝගික අයිතිය", "කළුකඩ වෙළඳාමේ අයිතිය", "ඒකාධිකාරී ලාභ ලැබීමේ අයිතිය", "බදු පැහැර හැරීමේ අයිතිය", "නිෂ්පාදනයේ සැබෑ ගුණාත්මක බව හා අඩංගු දේ විකෘති කර පෙන්වීම 2003 පනත යටතේ නීති විරෝධීය."),
    q("බහුසංස්කෘතික සමාජයක සාමාජිකයෙකු තුළ තිබිය යුතු 'සංස්කෘතික සාපේක්ෂතාවාදය' හෙවත් අන් සංස්කෘතීන්ට ගරු කිරීමේ ගුණය කුමක්ද?", "වෙනත් ප්‍රජාවක සිරිත් විරිත් තම සංස්කෘතියට වඩා පහත් යැයි නොසිතා අගය කිරීම", "සියලු සංස්කෘතීන් ප්‍රතික්ෂේප කිරීම", "තම භාෂාව අමතක කර දැමීම", "අනෙක් ජනවර්ග සමඟ වෙළඳාම් නොකිරීම", "සෑම සංස්කෘතියකටම ආවේණික වටිනාකමක් ඇති බව පිළිගැනීම සමාජ සමගිය ශක්තිමත් කරයි."),
    q("ශ්‍රී ලංකාව වැනි සංවර්ධනය වෙමින් පවතින රටක රජය 'සුබසාධන සේවා' පවත්වාගෙන යාමෙන් රටේ මානව සම්පතට ලැබුණු විශිෂ්ට ප්‍රතිඵලය කුමක්ද?", "ඉහළ සාක්ෂරතා අනුපාතය (92%+) හා දකුණු ආසියාවේ ඉහළම ආයු අපේක්ෂාවක් හිමි වීම", "කෘෂිකර්මාන්තය සම්පූර්ණයෙන් නතර වීම", "ජනගහනය සීඝ්‍රයෙන් අඩු වීම", "විශ්වවිද්‍යාල සංඛ්‍යාව ශුන්‍ය වීම", "නිදහස් අධ්‍යාපනය හා සෞඛ්‍ය සේවා නිසා ශ්‍රී ලංකාව ඉහළ මානව සංවර්ධන දර්ශකයක් අත්කර ගත්තේය."),
    q("තිරසාර සංවර්ධනය සඳහා 'කෘෂිකර්මාන්තයේදී' රසායනික පොහොර හා කෘමිනාශක අධි භාවිතය අඩු කිරීම වැදගත් වන්නේ ඇයි?", "පස, භූගත ජලය හා පාරිසරික පද්ධති දූෂණය වී අනාගත පරපුරට අහිතකර වීම වැළැක්වීමට", "අස්වැන්න සම්පූර්ණයෙන් නැති කිරීමට", "ආනයනික බදු වැඩි කිරීමට", "ගොවීන් ගොවිතැනින් ඉවත් කිරීමට", "කාබනික හා ඒකාබද්ධ පළිබෝධ පාලන ක්‍රම මඟින් පරිසරයත් ජනතා සෞඛ්‍යයත් රැකේ."),
    q("රටේ සංවර්ධන ව්‍යාපෘති සැලසුම් කිරීමේදී 'ස්වභාවික ජල පෝෂක ප්‍රදේශ හා කඩොලාන පරිසර පද්ධති' ආරක්ෂා කළ යුත්තේ ඇයි?", "ජල සම්පත රැකීමට, වෙරළ ඛාදනය වැළැක්වීමට හා ජෛව විවිධත්වය සුරැකීමට", "නාගරික ගොඩනැගිලි තැනීමට", "කර්මාන්තශාලා අපද්‍රව්‍ය බැහැර කිරීමට", "මහාමාර්ග පළල් කිරීමට", "සුනාමි හා කුණාටුවලින් වෙරළ ආරක්ෂා කිරීමේ ස්වභාවික පලිහක් ලෙස කඩොලාන ක්‍රියා කරයි."),
    q("මිශ්‍ර ආර්ථික ක්‍රමයක රජය 'මිල පාලනය' හෝ 'සහතික මිල' ක්‍රියාත්මක කරන ප්‍රධාන අවස්ථාවක් කුමක්ද?", "පාරිභෝගිකයා හා ගොවියා යන දෙදෙනාම වෙළඳපොළ අසාධාරණයෙන් රැකගැනීමට", "ව්‍යාපාරිකයන් සියල්ල බංකොලොත් කිරීමට", "අපනයන සම්පූර්ණයෙන් තහනම් කිරීමට", "විදේශ විනිමය අනුපාතය ශුන්‍ය කිරීමට", "අත්‍යවශ්‍ය ආහාර සඳහා උපරිම සිල්ලර මිලත් වී සඳහා සහතික මිලත් රජය නියම කරයි."),
    q("වෙළඳපොළ ආර්ථිකයක 'පාරිභෝගික ස්වෛරීභාවය' (Consumer Sovereignty) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "නිෂ්පාදකයා කුමක් නිපදවිය යුතුද යන්න අවසානයේ පාරිභෝගිකයාගේ ඉල්ලුම අනුව තීරණය වීම", "රජය සියලු භාණ්ඩ තෝරා දීම", "වෙළෙන්දා බලෙන් භාණ්ඩ විකිණීම", "ආනයන සම්පූර්ණයෙන් තහනම් කිරීම", "පාරිභෝගිකයන්ගේ රුචිකත්වය හා මිලදී ගැනීමේ තීරණ වෙළඳපොළ නිෂ්පාදනයට මග පෙන්වයි."),
    q("බහුසංස්කෘතික සමාජයක සාමකාමී සංවර්ධනය උදෙසා මාධ්‍ය හා අධ්‍යාපනය ඉටු කළ යුතු ප්‍රධාන කාර්යභාරය කුමක්ද?", "විවිධ සංස්කෘතීන් පිළිබඳ නිවැරදි අවබෝධය පතුරුවා වාර්ගික පූර්ව විනිශ්චයන් දුරු කිරීම", "එක් කණ්ඩායමක අයිතීන් පමණක් ප්‍රචාරය කිරීම", "ආගමික ගැටුම් අවුලුවාලීම", "මව් භාෂා අධ්‍යාපනය නතර කිරීම", "එකිනෙකාගේ උරුමයන්ට ගරු කරන පුරවැසි සංස්කෘතියක් ගොඩනැගීමට අධ්‍යාපනය හා මාධ්‍ය ප්‍රමුඛ වේ."),
    q("ශ්‍රී ලංකාවේ 'ජාතික අයවැය ලේඛනයේ' පුනරාවර්තන වියදම් සහ ප්‍රාග්ධන වියදම් අතර වෙනස කුමක්ද?", "පුනරාවර්තන වියදම් වැටුප් හා නඩත්තුවට වන අතර ප්‍රාග්ධන වියදම් මාර්ග, පාසල් හා යටිතල පහසුකම් ඉදිකිරීමටය", "දෙකම විදේශ ණය ගෙවීමට පමණි", "ප්‍රාග්ධන වියදම් විදුලි බිල් ගෙවීමට පමණි", "පුනරාවර්තන වියදම් ගුවන්තොටුපළ ඉදිකිරීමට පමණි", "දිගුකාලීන සංවර්ධනය උදෙසා රජය ප්‍රාග්ධන වියදම් හෙවත් ආයෝජන සිදු කිරීම අත්‍යවශ්‍යය."),
    q("සෑම පුරවැසියෙකුම 'තිරසාර පරිභෝජන රටාවකට' (Responsible Consumption) හුරු විය යුත්තේ ඇයි?", "සම්පත් නාස්තිය අඩු කර අනාගත පරපුරටත් පිරිසිදු පරිසරයක් ඉතිරි කිරීමට", "ආහාර හා ජලය වැඩිපුර ඉවත දැමීමට", "ප්ලාස්ටික් නිෂ්පාදනය දෙගුණ කිරීමට", "විදුලි පරිභෝජනය අසීමිතව වැඩි කිරීමට", "අවශ්‍ය ප්‍රමාණයට පමණක් පරිභෝජනය කර ජලය, විදුලිය හා ආහාර ඉතිරි කිරීම SDG 12 ඉලක්කයයි."),
    q("වෙළඳපොළේ අතරමැදියන්ගේ අසාධාරණ ලාභය අවම කර ගොවියාටත් පාරිභෝගිකයාටත් සහන සැලසීමට යෝග්‍ය ආර්ථික ආයතනය කුමක්ද?", "සමුපකාර හා ඍජු ගොවි වෙළඳසැල් ජාලය", "පෞද්ගලික ඒකාධිකාර", "කළුකඩ වෙළඳ මධ්‍යස්ථාන", "විදේශීය කොටස් වෙළඳපොළ", "නිෂ්පාදකයා හා පාරිභෝගිකයා සෘජුව සම්බන්ධ කරන සමුපකාර ක්‍රමය දෙපාර්ශ්වයටම සාධාරණ මිලක් ලබා දේ."),
    q("ශ්‍රී ලංකාවේ බහුසංස්කෘතික සමාජය තුළ සෑම පුරවැසියෙකුටම පොදු වූ 'ශ්‍රී ලාංකික අනන්‍යතාවක්' ගොඩනගා ගැනීම වැදගත් වන්නේ ඇයි?", "වාර්ගික බෙදීම් ඉක්මවා රටේ ආර්ථික, සමාජ හා ප්‍රජාතන්ත්‍රවාදී දියුණුවට සැම එක්ව දායක වීමට", "සියලු ප්‍රාදේශීය උරුමයන් අමතක කිරීමට", "පළාත් සභා නවය වසා දැමීමට", "විදේශ සංචාරකයන් වැළැක්වීමට", "ජාති ආගම් භේදයකින් තොරව මව්බිමේ දියුණුව වෙනුවෙන් එකමුතුවීම ශ්‍රී ලාංකික අනන්‍යතාවයි."),
    q("පාරිසරික තිරසාරභාවය උදෙසා 'ප්ලාස්ටික් වෙනුවට පරිසර හිතකාමී ආදේශක' (රෙදි බෑග්, කඩදාසි ඇසුරුම්) භාවිතය ප්‍රවර්ධනය කිරීමෙන් සිදුවන්නේ කුමක්ද?", "දිරාපත් නොවන පොලිතීන් අපද්‍රව්‍ය පසෙහි හා සාගරයේ එකතු වීම අවම වීම", "කර්මාන්තශාලා දූෂණය වැඩි වීම", "මුහුදු ජීවීන් වඳ වී යාම", "නාගරික කානු පද්ධති අවහිර වීම", "එක්වරක් භාවිත කර ඉවත දමන ප්ලාස්ටික් සීමා කිරීමෙන් සමුද්‍ර හා ගොඩබිම් පරිසර පද්ධති ආරක්ෂා වේ."),
    q("රාජ්‍ය සුබසාධන සේවා ක්‍රියාත්මක කිරීමේදී 'නිසි ඉලක්කගත කිරීම' (Proper Targeting) වැදගත් වන්නේ ඇයි?", "සැබවින්ම අසරණ හා අඩු ආදායම්ලාභී පවුල්වලට රාජ්‍ය ආධාර නිවැරදිව හිමිවීමට", "ධනවත් පවුල්වලට පමණක් සහනාධාර දීමට", "රජයේ අයවැය හිඟය දස ගුණයකින් වැඩි කිරීමට", "පාසල් අධ්‍යාපනය නතර කිරීමට", "සීමිත රාජ්‍ය මුදල් අවභාවිත නොවී සුදුසුම ප්‍රතිලාභීන්ට සහනය ලැබීම ඉන් තහවුරු වේ."),
    q("මිශ්‍ර ආර්ථික ක්‍රමයක රාජ්‍ය අංශය විසින් පෞද්ගලික අංශයට නොදී තබා ගැනීමට බොහෝ විට පෙළඹෙන 'පොදු භාණ්ඩ' (Public Goods) මොනවාද?", "ජාතික ආරක්ෂාව, මහාමාර්ග, වීදි ආලෝකකරණය සහ පොදු උද්‍යාන", "සුඛෝපභෝගී රථවාහන සහ ආභරණ", "පෞද්ගලික ජංගම දුරකථන", "විලාසිතා ඇඳුම් පැළඳුම්", "මුදල් නොගෙවූ අය පවා වැළැක්විය නොහැකි පොදු සේවාවන් ලාභ නොබලා රජය මඟින් සපයනු ලැබේ."),
    q("ආර්ථික ක්‍රමයක් සැලසුම් කිරීමේදී ඕනෑම සමාජයක් විසඳා ගත යුතු 'මූලික ආර්ථික ප්‍රශ්න තුන' මොනවාද?", "කුමක් නිපදවන්නේද, කෙසේ නිපදවන්නේද සහ කවුරුන් සඳහා නිපදවන්නේද යන්න", "කවුරු ඡන්දය දෙන්නේද, කවුරු අගමැති වන්නේද යන්න", "කුමන විභාගයක් තබන්නේද යන්න", "කුමන නගරයේ පන්සල හදන්නේද යන්න", "සම්පත් හිඟකම හේතුවෙන් සෑම ආර්ථිකයක්ම මෙම තීරණාත්මක ප්‍රශ්න තුනට පිළිතුරු සැපයිය යුතුය."),
    q("වෙළඳපොළේදී 'නිෂ්පාදන සාධකවලට ගෙවන ප්‍රතිලාභ' නිවැරදිව ගැළපෙන පිළිතුර කුමක්ද?", "භූමියට බදු කුලී, ශ්‍රමයට වැටුප්, ප්‍රාග්ධනයට පොලිය සහ ව්‍යවසායකත්වයට ලාභය", "සියල්ලටම රේගු බදු පමණි", "භූමියට පොලිය සහ ශ්‍රමයට බදු", "ප්‍රාග්ධනයට වැටුප් සහ භූමියට ලාභය", "නිෂ්පාදන ක්‍රියාවලියට දායක වන සෑම සාධකයකටම ආර්ථිකයේදී නිශ්චිත ආදායම් වර්ගයක් හිමිවේ."),
    q("ශ්‍රී ලංකාවේ 'පාසල් සිසුන් සඳහා වන සුරක්ෂා රක්ෂණ යෝජනා ක්‍රමය' මඟින් ලබාදෙන සුබසාධන සේවාව කුමක්ද?", "පාසල් දරුවන්ට සෞඛ්‍ය, හදිසි අනතුරු හා ආපදා රක්ෂණ ආවරණයක් නොමිලේ ලබාදීම", "සිසුන්ට විදේශ ගමන් බලපත්‍ර දීම", "වාහන බලපත්‍ර ලබාදීම", "රැකියා බැංකු ණය දීම", "දිවයිනේ සියලුම පාසල් සිසුන්ගේ සෞඛ්‍ය හා අධ්‍යාපන අඛණ්ඩතාව රැකීමට මෙම සුබසාධන ක්‍රමය දායක වේ."),
    q("ශ්‍රී ලංකාවේ 'රාජ්‍ය විශ්‍රාම වැටුප් ක්‍රමය' මඟින් ඉටු කරන සමාජ ආරක්ෂණ කාර්යය කුමක්ද?", "රාජ්‍ය සේවයේ නියුතුව විශ්‍රාම ලැබූ ජ්‍යෙෂ්ඨ පුරවැසියන්ට ජීවිතාන්තය දක්වා මාසික ආදායමක් තහවුරු කිරීම", "විශ්‍රාමිකයන්ගෙන් විශේෂ දඩ අය කිරීම", "තරුණයන්ට පමණක් පඩි ගෙවීම", "පාසල් පෙළපොත් මුද්‍රණය කිරීම", "වයස්ගත වූ පසු වැඩ කළ නොහැකි අවධියේදී ගෞරවාන්විත ජීවිතයක් ගත කිරීමට විශ්‍රාම වැටුප ඉවහල් වේ."),
    q("රටේ සෞඛ්‍ය සේවාවේ 'ප්‍රාථමික සෞඛ්‍ය සත්කාරය' (Primary Health Care) ශක්තිමත් කිරීමෙන් අත්වන වාසිය කුමක්ද?", "රෝග වැළැක්වීම, එන්නත්කරණය හා මූලික ප්‍රතිකාර ගමේදීම ලැබී ප්‍රධාන රෝහල් තදබදය අඩු වීම", "සියලු ප්‍රාදේශීය ඩිස්පෙන්සරි වැසී යාම", "ඖෂධ මිල දස ගුණයකින් ඉහළ යාම", "රෝගීන් විදේශගත වීමට සිදු වීම", "ශ්‍රී ලංකාවේ ග්‍රාමීය මාතෘ සායන හා ප්‍රාථමික වෛද්‍ය ඒකක පොදු සෞඛ්‍යයේ සාර්ථකත්වයට මුල් විය."),
    q("රජයේ අයවැයක 'අතිරික්ත අයවැයක්' (Surplus Budget) යනුවෙන් හැඳින්වෙන්නේ කුමන තත්ත්වයද?", "රජයේ අපේක්ෂිත මුළු ආදායම මුළු වියදමට වඩා වැඩි වීම", "වියදම ආදායම මෙන් දෙගුණයක් වීම", "බදු ආදායම ශුන්‍ය වීම", "විදේශ ණය ගෙවීම නතර වීම", "ආදායම ඉතිරි වීමෙන් රාජ්‍ය ණය බර අඩු කර ගැනීමට හා සංචිත ගොඩනගා ගැනීමට හැකිවේ."),
    q("රජය විසින් මුද්‍රණ යන්ත්‍රවලින් අසීමිතව 'මුදල් අච්චු ගැසීමෙන්' (Money Printing) ආර්ථිකයට සිදුවන අහිතකර බලපෑම කුමක්ද?", "භාණ්ඩ ප්‍රමාණයට වඩා මුදල් සංසරණය වැඩි වී දැඩි උද්ධමනයක් හා මුදලේ අගය පිරිහීමක් ඇති වීම", "සියලු භාණ්ඩ මිල ඉතා අඩු වීම", "රටේ නිෂ්පාදනය ක්ෂණිකව දෙගුණ වීම", "විදේශ විනිමය අගය ශක්තිමත් වීම", "නිෂ්පාදන වර්ධනයකින් තොරව මුදල් සැපයුම වැඩි කිරීම මිල මට්ටම් සීඝ්‍රයෙන් ඉහළ නංවයි."),
    q("පාරිභෝගික භාණ්ඩවල ඇසුරුමෙහි 'ව්‍යාජ ලෙස බර වැඩි කර පෙන්වීම හෝ අපිරිසිදු ද්‍රව්‍ය කලවම් කිරීම' (Adulteration) සම්බන්ධ නීතිමය තත්ත්වය කුමක්ද?", "ආහාර පනත හා පාරිභෝගික අධිකාරි පනත යටතේ දඬුවම් ලැබිය හැකි බරපතළ වරදකි", "වෙළෙන්දාට ඇති නීත්‍යානුකූල නිදහසකි", "අපනයන ප්‍රවර්ධන උපක්‍රමයකි", "සමුපකාර ප්‍රතිපත්තියකි", "ගම්මිරිස්වලට පැපොල් ඇට හෝ කිරිවලට ජලය කලවම් කිරීම වැනි වංචා මහජන සෞඛ්‍යයට හානිකරය."),
    q("වෙළඳපොළේදී 'උපරිම සිල්ලර මිල' (MRP - Maximum Retail Price) රජය විසින් ගැසට් කරනු ලබන්නේ කවර භාණ්ඩ සඳහාද?", "සහල්, සීනි, පරිප්පු, ඖෂධ සහ බිත්තර වැනි අත්‍යවශ්‍ය පාරිභෝගික ද්‍රව්‍ය සඳහා", "දියමන්ති හා රන් ආභරණ සඳහා පමණි", "පෞද්ගලික ගුවන් යානා සඳහා", "විදේශීය කෞතුක භාණ්ඩ සඳහා", "සාමාන්‍ය ජනතාවගේ ජීවන වියදම පාලනය කර ගැනීමට අත්‍යවශ්‍ය භාණ්ඩ මත පාලන මිල පැනවේ."),
    q("පාරිභෝගිකයා විසින් ණයට භාණ්ඩ මිලදී ගැනීමේදී හෝ කල්බදු (Leasing/Hire Purchase) ගිවිසුමකට අත්සන් කිරීමේදී පරීක්ෂා කළ යුතු ප්‍රධාන කරුණ කුමක්ද?", "පොලී අනුපාතය, වාරික ගණන, සැඟවුණු ගාස්තු හා ගිවිසුම් කොන්දේසි සම්පූර්ණයෙන් කියවා බැලීම", "හිස් කොළවලට ඇස් පියාගෙන අත්සන් කිරීම", "මාසික ආදායම නොබලා ණය ගැනීම", "පිටපතක් නොඉල්ලා සිටීම", "මූල්‍ය සාක්ෂරතාව සහිත පාරිභෝගිකයෙකු ගිවිසුම් කොන්දේසි පැහැදිලිව අවබෝධ කරගෙන තීරණ ගනී."),
    q("වෙළඳපොළේ භාණ්ඩ හා සේවා මිලදී ගැනීමේදී පාරිභෝගිකයා සතු 'පාරිභෝගික අධ්‍යාපනය ලැබීමේ අයිතිය' යනු කුමක්ද?", "විචක්ෂණශීලී තෝරාගැනීම් කිරීමට අවශ්‍ය දැනුම හා කුසලතා පාසලේ සිටම ලබාගැනීමේ අයිතිය", "නොමිලේ භාණ්ඩ ලබාගැනීමේ අයිතිය", "වෙළඳසැලක් පැහැර ගැනීමේ අයිතිය", "බදු නොගෙවා සිටීමේ අයිතිය", "පාරිභෝගික අයිතීන් හා වෙළඳ උපක්‍රම ගැන දැනුවත් පුරවැසියා පහසුවෙන් රැවටීමට ලක් නොවේ."),
    q("බහුසංස්කෘතික සමාජයක විවිධ ප්‍රජාවන්ගේ 'සංස්කෘතික උරුමයන්' ප්‍රදර්ශනය කරන ජාතික ආයතනයක් කුමක්ද?", "ජාතික කෞතුකාගාරය සහ සංස්කෘතික කටයුතු දෙපාර්තමේන්තුව", "ශ්‍රී ලංකා රේගුව", "මැතිවරණ කොමිසම", "විගණකාධිපති දෙපාර්තමේන්තුව", "රටේ සෑම ජන කොටසකම ඓතිහාසික කලා හා සංස්කෘතික උරුමයන් කෞතුකාගාරවල ආරක්ෂා කෙරේ."),
    q("ශ්‍රී ලංකාවේ 'තෛපොංගල්' උත්සවය හින්දු ප්‍රජාව විසින් සමරනු ලබන්නේ කුමන ස්වභාවික හා කෘෂිකාර්මික කෘතඥතාව පළ කිරීමටද?", "සාරවත් අස්වැන්නක් ලබාදීම වෙනුවෙන් හිරු දෙවියන්ට හා සොබාදහමට කෘතගුණ සැලකීමට", "විභාග අවසන් වීම සැමරීමට", "මුහුදු යාම තහනම් කිරීමට", "නගර සභා අයවැය සැමරීමට", "සූර්ය වන්දනාව, කිරි ඉතිරවීම හා ගව සම්පතට ගරු කිරීම මෙම අස්වනු උත්සවයේ විශේෂ අංග වේ."),
    q("ඉස්ලාම් බැතිමතුන්ගේ 'රාමසාන්' (ඊදුල් ෆිතර්) හා 'හජ්' උත්සව මඟින් සමාජයට දෙන ප්‍රධාන සමාජීය පණිවිඩය කුමක්ද?", "ආත්ම දමනය, දිළිඳුන්ට දන් දීම (සකාත්), සමානාත්මතාව හා සහෝදරත්වය", "ධනය රැස් කර සැඟවීම", "පරිසරය විනාශ කිරීම", "අසල්වැසියන් සමඟ අමනාප වීම", "පුණ්‍ය කටයුතු හා දුප්පතුන් සමඟ සතුට බෙදාගැනීම ඉස්ලාමීය සංස්කෘතික උත්සවවල කැපී පෙනේ."),
    q("ක්‍රිස්තියානි ප්‍රජාව සමරන 'නත්තල්' උත්සවයේ ප්‍රධාන අධ්‍යාත්මික හා සමාජීය තේමාව කුමක්ද?", "ලෝක සාමය, ප්‍රේමය, සමාව දීම සහ අසරණයන් සමඟ බෙදාගැනීම", "යුද ගැටුම් වැඩි කිරීම", "ජාතිවාදය පැතිරවීම", "සේවක අයිතීන් කප්පාදු කිරීම", "සියලු ආගමික උත්සව මෙන්ම නත්තලද පවුල් සමගිය හා මානව දයාව ප්‍රවර්ධනය කරයි."),
    q("සිංහල හා හින්දු 'අලුත් අවුරුදු' උත්සවය ශ්‍රී ලංකාවේ ජාතික ඒකාග්‍රතාවට වැදගත් වන්නේ කෙසේද?", "සිංහල හා දෙමළ ජන කොටස් දෙකම එකම සූර්ය සංක්‍රාන්ති නැකැත් අනුව සාමූහිකව සමරන බැවිනි", "එක් ජන කොටසකට පමණක් සීමා වූ නිසා", "අවුරුදු ක්‍රීඩා තහනම් කර ඇති නිසා", "රජයේ කාර්යාල වසා නොතබන නිසා", "අසල්වැසියන් අතර කෑම බීම හුවමාරුව හා සාම්ප්‍රදායික ක්‍රීඩා සමාජ බැඳීම් ශක්තිමත් කරයි."),
    q("බහුසංස්කෘතික සමාජයක 'අන්තර්-ආගමික සහජීවනය' තහවුරු කිරීම සඳහා පුරවැසියන් වළක්වා ගත යුතු ක්‍රියාව කුමක්ද?", "වෙනත් ආගමක විශ්වාස, පූජ්‍ය පක්ෂය හෝ ආගමික සංකේත අවඥාවට ලක් කිරීම", "වෙනත් ආගමික උත්සවයකට සුබ පැතීම", "සර්ව ආගමික සාම කමිටු පැවැත්වීම", "දෙවන ජාතික භාෂාව ඉගෙනීම", "ආගමික ගෞරවය ආරක්ෂා කිරීම ජාතික සාමය පවත්වාගැනීමට අත්‍යවශ්‍යය."),
    q("ශ්‍රී ලංකාවේ 'තිරසාර සංවර්ධන පනත' (2017 අංක 19) සම්මත කරනු ලැබුවේ කුමන අරමුණක් ඉටු කර ගැනීමටද?", "එක්සත් ජාතීන්ගේ තිරසාර සංවර්ධන ඉලක්ක 2030 ජාතික ප්‍රතිපත්තිවලට ඇතුළත් කර සම්බන්ධීකරණය කිරීමට", "සියලු ජාතික වනෝද්‍යාන වසා දැමීමට", "පාරිසරික නීති අවලංගු කිරීමට", "බදු අය කිරීම නතර කිරීමට", "තිරසාර සංවර්ධන සභාව පිහිටුවමින් ආර්ථික, සමාජ හා පාරිසරික සැලසුම් ඒකාබද්ධ කිරීමට මෙම පනත ගෙන එන ලදී."),
    q("පාරිසරික ආරක්ෂණයේදී 'ප්‍රභවස්ථාන දූෂණය' (Point Source Pollution) සඳහා උදාහරණයක් වන්නේ කුමක්ද?", "කර්මාන්තශාලාවක අපජල නළයකින් සෘජුවම ගංගාවකට විෂ රසායන මුදා හැරීම", "ප්‍රමාණවත් වර්ෂාපතනයක් ලැබීම", "ගස් වැල් වර්ධනය වීම", "සූර්ය පැනල සවි කිරීම", "අපජලය පිරිපහදු කර මුදාහැරීමට මධ්‍යම පරිසර අධිකාරියේ පරිසර ආරක්ෂණ බලපත්‍රය අනිවාර්ය වේ."),
    q("පරිසරයට එකතු වන 'විද්‍යුත් අපද්‍රව්‍ය' (E-Waste - පැරණි බැටරි, ජංගම දුරකථන, පරිගණක) සාමාන්‍ය කසළ සමඟ නොදැමිය යුත්තේ ඇයි?", "ඒවායේ ඊයම්, රසදිය හා කැඩ්මියම් වැනි බැර ලෝහ අඩංගු බැවින් පස හා ජලය දැඩි ලෙස විෂ වන නිසා", "ඒවා ඉතා ඉක්මනින් දිරාපත් වී පොහොර වන නිසා", "ඒවා ආහාරයට ගත හැකි නිසා", "ගංවතුර පාලනය කරන නිසා", "විද්‍යුත් අපද්‍රව්‍ය නිසි ප්‍රතිචක්‍රීකරණ මධ්‍යස්ථාන වෙත භාර දිය යුතුය."),
    q("ගෝලීය පාරිසරික ගැටලුවක් වූ 'ඕසෝන් ස්ථරය ක්ෂය වීම' වැළැක්වීම සඳහා CFC වායු තහනම් කළ 1987 ජාත්‍යන්තර ගිවිසුම කුමක්ද?", "මොන්ට්‍රියල් සම්මුතිය (Montreal Protocol)", "පැරිස් ගිවිසුම", "ජිනීවා සම්මුතිය", "සාර්ක් ප්‍රඥප්තිය", "ශීතකරණ හා වායු සමීකරණවල භාවිත කළ CFC තහනම් කිරීමෙන් පාරජම්බුල කිරණවලින් පෘථිවිය රැකගත හැකි විය."),
    q("පරිසරයට හානි නොවන පරිදි බලශක්තිය නිපදවීම සඳහා 'ජෛව වායු ඒකක' (Biogas Units) භාවිතයෙන් ලැබෙන ද්විත්ව වාසිය කුමක්ද?", "කාබනික අපද්‍රව්‍ය හා සත්ත්ව මලද්‍රව්‍ය කළමනාකරණය වී පිරිසිදු ඉවුම් පිහුම් ගෑස් හා කාබනික පොහොර ලැබීම", "ප්ලාස්ටික් ප්‍රමාණය වැඩි වීම", "වනාන්තර කැපීම වැඩි වීම", "වායු දූෂණය ඉහළ යාම", "ග්‍රාමීය නිවාස, ගොවිපළ හා පාසල් සඳහා ජෛව වායු තාක්ෂණය ඉතා ලාභදායී හා හරිත විසඳුමකි."),
    q("වෙළඳපොළේදී 'පරිසර හිතකාමී හරිත පාරිභෝගිකයෙකු' (Green Consumer) ලෙස හැසිරීම යනු කුමක්ද?", "අවම ඇසුරුම් සහිත, ප්‍රතිචක්‍රීකරණය කළ හැකි හා පරිසරයට හානි නොවන නිෂ්පාදන තෝරාගැනීම", "වැඩිපුර පොලිතීන් බෑග් ඉල්ලා සිටීම", "ආහාර අපතේ දැමීම", "අනාරක්ෂිත රසායනික භාණ්ඩ තෝරාගැනීම", "පාරිභෝගිකයන් හරිත නිෂ්පාදන ඉල්ලා සිටින විට ව්‍යාපාරිකයන්ද පරිසර හිතකාමී වීමට පෙළඹේ."),
    q("ශ්‍රී ලංකාවේ 'වෙරළ සංරක්ෂණ හා වෙරළ සම්පත් කළමනාකරණ දෙපාර්තමේන්තුව' වෙරළ කලාපය තුළ ඉදිකිරීම් සීමා කරන්නේ ඇයි?", "වෙරළ ඛාදනය පාලනයට, සමුද්‍ර දූෂණය වැළැක්වීමට හා සුනාමි වැනි ආපදා අවදානම් අඩු කිරීමට", "ධීවර රැකියාව නතර කිරීමට", "මුහුදු සංචාරක ව්‍යාපාරය තහනම් කිරීමට", "වරායවල් වසා දැමීමට", "වෙරළ තීරයේ ස්වභාවික වැලි වැටි හා කොරල්පර ආරක්ෂා කිරීම ජාතික ආරක්ෂාවටද වැදගත් වේ."),
    q("සුළි සුළං හෝ අධික වර්ෂාවකදී 'කාලගුණ විද්‍යා දෙපාර්තමේන්තුව' හා 'ජාතික ගොඩනැගිලි පර්යේෂණ සංවිධානය' (NBRO) ඉටු කරන කාර්යය කුමක්ද?", "අධික වැසි, සුළං හා නායයෑම් අවදානම් පිළිබඳ පූර්ව අනතුරු ඇඟවීම් නිකුත් කිරීම", "බදු අය කිරීම", "මැතිවරණ පැවැත්වීම", "පෙළපොත් බෙදාදීම", "කඳුකර ප්‍රදේශවල නායයෑම් රතු නිවේදන නිකුත් කර ජීවිත බේරා ගැනීමට NBRO ක්‍රියා කරයි."),
    q("ආපදාවකට පසුව 'මානසික සෞඛ්‍ය සහාය' (Psychosocial Support) ලබාදීම වැදගත් වන්නේ ඇයි?", "නිවාස හා ඥාතීන් අහිමි වීමෙන් ඇති වූ කම්පනය හා බිය දුරු කර යළි ජීවිතය ගොඩනගා ගැනීමට", "ආර්ථික බදු වැඩි කිරීමට", "පාසල් වසා දැමීමට", "පූර්ව අනතුරු නතර කිරීමට", "භෞතික නිවාස තැනීම මෙන්ම විපතට පත් දරුවන්ගේ හා වැඩිහිටියන්ගේ මානසික සුවයද ඉතා වැදගත්ය."),
    q("සංවර්ධන ක්‍රියාවලියේදී 'මිනිස් සම්පතට ආයෝජනය කිරීම' (Investing in Human Capital) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "ජනතාවගේ අධ්‍යාපනය, සෞඛ්‍යය, පෝෂණය හා වෘත්තීය කුසලතා සංවර්ධනය සඳහා මුදල් වැය කිරීම", "යන්ත්‍ර සූත්‍ර පමණක් ආනයනය කිරීම", "වනාන්තර කපා දැමීම", "වැටුප් කප්පාදු කිරීම", "දැනුමෙන් හා නිරෝගී බවින් පොහොසත් ශ්‍රම බලකායක් ඕනෑම රටක ප්‍රබලම සංවර්ධන සාධකයයි."),
    q("වෙළඳපොළ ආර්ථික ක්‍රමයේදී රජය 'නියාමකයෙකු' (Regulator) ලෙස ක්‍රියා කරන ප්‍රධාන ආයතනයකට උදාහරණයක් කුමක්ද?", "ශ්‍රී ලංකා මහජන උපයෝගිතා කොමිෂන් සභාව (PUCSL) සහ පාරිභෝගික කටයුතු අධිකාරිය", "පාසල් විවාද සමාජය", "ග්‍රාමීය ක්‍රීඩා සමාජය", "සාහිත්‍ය සංගමය", "විදුලිය, ජලය හා අත්‍යවශ්‍ය සේවාවල ගුණාත්මක බව හා සාධාරණ මිල නියාමනය කිරීම රජයේ වගකීමකි."),
    q("ධනවාදී හා සමාජවාදී ආර්ථික ක්‍රමවල යහපත් ලක්ෂණ එක් කළ 'මිශ්‍ර ආර්ථිකය' ශ්‍රී ලංකාවට වඩාත් ගැළපෙන්නේ ඇයි?", "පෞද්ගලික ව්‍යවසාය හරහා ආර්ථික වර්ධනයත් රාජ්‍ය මැදිහත්වීම හරහා සමාජ සුබසාධනයත් රැකෙන බැවිනි", "විදේශ වෙළඳාම සම්පූර්ණයෙන් නැති වන බැවිනි", "පෞද්ගලික දේපළ තහනම් වන බැවිනි", "සියලු බැංකු වසා දැමීමට හැකි බැවිනි", "වෙළඳපොළ කාර්යක්ෂමතාව සමාජ සාධාරණත්වය සමඟ සමබර කිරීම මිශ්‍ර ආර්ථිකයේ ශක්තියයි."),
    q("රටක 'ආර්ථික වර්ධනය' (Economic Growth) සහ 'ආර්ථික සංවර්ධනය' (Economic Development) අතර ප්‍රධාන වෙනස කුමක්ද?", "වර්ධනය යනු නිෂ්පාදනයේ ප්‍රමාණාත්මක වැඩිවීම පමණක් වන අතර සංවර්ධනයට ජීවන තත්ත්වය, සෞඛ්‍යය හා අධ්‍යාපන දියුණුවද ඇතුළත් වේ", "දෙකම සම්පූර්ණයෙන්ම එකම සංකල්ප වේ", "සංවර්ධනය යනු උද්ධමනය වැඩි වීමයි", "වර්ධනය යනු ජනගහනය අඩු වීමයි", "GDP ඉහළ ගියද ආදායම සාධාරණව නොබෙදේ නම් සැබෑ ආර්ථික සංවර්ධනයක් සිදු නොවේ."),
    q("ශ්‍රී ලංකාවේ 'ග්‍රාමීය ණයගැතිභාවය' අවම කර දිළිඳු ගොවීන් හා කාන්තාවන් නගා සිටුවීමට වැදගත් වන ක්‍රමවේදය කුමක්ද?", "සාධාරණ පොලී අනුපාත යටතේ ක්ෂුද්‍ර මූල්‍ය හා සමුපකාර බැංකු පහසුකම් සැලසීම", "අධික පොලී ගිනි පොලීකරුවන්ට ඉඩ දීම", "බැංකු ශාඛා වසා දැමීම", "අස්වැන්න මිලදී ගැනීම නතර කිරීම", "සාධාරණ මූල්‍ය ප්‍රවේශය හා මූල්‍ය සාක්ෂරතාව ග්‍රාමීය ආර්ථිකය ශක්තිමත් කරයි."),
    q("බහුසංස්කෘතික සමාජයක විවිධ ජන කොටස්වලට තම 'ආගමික හා සංස්කෘතික අනන්‍යතාවයන්' ඉගෙනීමට අධ්‍යාපනයේදී ලබාදී ඇති අයිතිය කුමක්ද?", "මව්භාෂාවෙන් අධ්‍යාපනය ලැබීමේ හා තම ආගම ඉගෙනීමේ පහසුකම් පාසල් තුළ සැලසීම", "සියලු දෙනාම එක් ආගමක් පමණක් ඉගෙනීමට බල කිරීම", "මව්භාෂා පාසල් වසා දැමීම", "වෙනත් සංස්කෘතීන් තහනම් කිරීම", "සිංහල, දෙමළ හා ඉංග්‍රීසි මාධ්‍ය පාසල් සහ ආගම් විෂයන් ඉගැන්වීම ශ්‍රී ලංකාවේ විවිධත්ව ගරුත්වය පෙන්වයි."),
    q("පාරිසරික තිරසාරභාවය උදෙසා 'පාසල් වත්තේ හා ගෙවත්තේ රුක් රෝපණය' කිරීමෙන් ලැබෙන පාරිසරික ප්‍රයෝජන මොනවාද?", "කාබන් ඩයොක්සයිඩ් අවශෝෂණය කිරීම, පාංශු ඛාදනය වැළැක්වීම හා ජෛව විවිධත්වය වර්ධනය කිරීම", "වැසි අඩු වී කාන්තාර ඇති වීම", "වායු උෂ්ණත්වය අධික ලෙස ඉහළ යාම", "ජල උල්පත් සිඳී යාම", "ශාක වැස්ම වැඩි කිරීම දේශගුණික විපර්යාස අවම කිරීමේ සරලම හා සාර්ථකම ක්‍රමයකි."),
    q("රටේ සංවර්ධන ව්‍යාපෘතිවල 'මහජන සහභාගිත්වය' ලබාගැනීම තිරසාර සංවර්ධනයට උපකාරී වන්නේ කෙසේද?", "ප්‍රදේශයේ ජනතාවගේ සැබෑ අවශ්‍යතාවලට ගැළපෙන ව්‍යාපෘති නිර්මාණය වී ඒවා දිගුකාලීනව රැකබලා ගැනීමෙන්", "ව්‍යාපෘති මුදල් අපතේ යාමෙන්", "ජනතාවට ව්‍යාපෘති ගැන කිසිවක් නොදැන්වීමෙන්", "ව්‍යාපෘති අතරමග නැවැත්වීමෙන්", "ජනතාව සංවර්ධනයේ හිමිකරුවන් බවට පත් වූ විට එම සම්පත් ආරක්ෂා කිරීමේ වගකීම ඔවුහුම භාර ගනිති."),
    q("තිරසාර සංවර්ධනය යනු කුමන ආකාරයේ සංවර්ධනයක්ද යන්න සරලවම ප්‍රකාශ වන අදහස කුමක්ද?", "පරිසරය විනාශ නොකර, සමාජ සාධාරණත්වය රැකගනිමින් අනාගත පරපුරේ අයිතීන්ද සුරකින ආර්ථික ප්‍රගතිය", "ස්වභාවික සම්පත් සියල්ල වසර පහකින් අවසන් කරන සංවර්ධනය", "ධනවතුන් කිහිප දෙනෙකුගේ ලාභය පමණක් වැඩි කිරීම", "පාරිසරික නීති සම්පූර්ණයෙන් ඉවත් කර කර්මාන්ත හැදීම", "ආර්ථිකය, සමාජය සහ පරිසරය යන ත්‍රිත්වයේ සමබර පැවැත්ම තිරසාර සංවර්ධනයේ සැබෑ හරයයි."),
    q("ශ්‍රී ලංකාවේ 'ව්‍යවසායකත්වය' (Entrepreneurship) ප්‍රවර්ධනය කිරීමෙන් තරුණ විරැකියාවට ලැබෙන විසඳුම කුමක්ද?", "රැකියා ඉල්ලා සිටින්නන් වෙනුවට අන් අයටත් රැකියා සපයන නව ව්‍යාපාර හිමිකරුවන් බිහිවීම", "සියලු තරුණයන් විදේශගත වීම පමණි", "රජයේ වැටුප් බර දෙගුණ වීම", "කර්මාන්තශාලා වැසී යාම", "නවෝත්පාදන හා ස්වයං රැකියා දිරිගැන්වීම ජාතික ආර්ථිකයට නව ජවයක් එක් කරයි."),
    q("පාරිභෝගිකයෙකු වශයෙන් භාණ්ඩයක ඇති 'අඩංගු ද්‍රව්‍ය හා පෝෂණ ලේබලය' කියවා බැලීම වැදගත් වන්නේ ඇයි?", "අසාත්මිකතා ඇති කරන ද්‍රව්‍ය, අධික සීනි හෝ ලුණු ප්‍රමාණය හඳුනාගෙන සෞඛ්‍ය ආරක්ෂිතව තෝරාගැනීමට", "භාණ්ඩයේ මිල දෙගුණ කිරීමට", "ඇසුරුම කුණු කූඩයට දැමීමට", "වෙළෙන්දාට ත්‍යාග දීමට", "ශ්‍රී ලංකාවේ බීම වර්ගවල සීනි මට්ටම පෙන්වන වර්ණ සංකේත (Traffic Light Labelling) ක්‍රමයද හඳුන්වා දී ඇත."),
    q("රටේ ආර්ථිකයේ 'නොවිධිමත් අංශයේ' (Informal Sector - දෛනික වැටුප් ලබන්නන්, සුළු වෙළෙන්දන්) සේවකයන් සඳහා සමාජ ආරක්ෂණය වැදගත් වන්නේ ඇයි?", "ඔවුන්ට EPF හෝ විශ්‍රාම වැටුප් ආවරණ නොමැති බැවින් අසනීප හා මහලු වියේදී දිළිඳු වීම වැළැක්වීමට", "ඔවුන්ට අධික ආදායම් බදු පැනවීමට", "ඔවුන්ගේ වෙළඳාම තහනම් කිරීමට", "ඔවුන්ට සෞඛ්‍ය සේවා නොදීමට", "ගොවි හා ධීවර විශ්‍රාම වැටුප් හා ස්වයං රැකියා රක්ෂණ ක්‍රම හරහා මෙම අංශයටද ආරක්ෂාව සැලසිය යුතුය."),
    q("ගංවතුර හා නියඟය යන දෙවර්ගයේම බලපෑම් අවම කර ගැනීමට ශ්‍රී ලංකාවේ සාම්ප්‍රදායික හා නවීන විසඳුම කුමක්ද?", "පුරාණ වැව් පද්ධති ප්‍රතිසංස්කරණය කර වැසි ජලය රැස් කිරීම හා ජල පෝෂක වනාන්තර රැකීම", "සියලු වැව් ගොඩකර ගොඩනැගිලි තැනීම", "වැසි ජලය සම්පූර්ණයෙන් මුහුදට හරවා යැවීම", "වනාන්තර කපා දැමීම", "අධික වැසි කාලයේ ජලය ගබඩා කර නියං කාලයේදී භාවිත කිරීම තිරසාර ජල කළමනාකරණයයි."),
    q("බහුසංස්කෘතික සමාජයක 'ජාතික ගීය සියලු පුරවැසියන්ට තේරුම් ගත හැකි ලෙස ගරු කිරීම' වැදගත් වන්නේ ඇයි?", "මව්බිමට ඇති ආදරය හා පොදු අයිතිවාසිකම සෑම ප්‍රජාවකටම සමානව දැනෙන බැවිනි", "එක් ජන කොටසක් පමණක් බැහැර කිරීමට", "ජාතික උත්සව නතර කිරීමට", "ආණ්ඩුක්‍රම ව්‍යවස්ථාව අහෝසි කිරීමට", "ජාතික සංකේතවලට සැමගේ ගෞරවය හිමිවීම රටේ ඒකාග්‍රතාව හා සාමකාමී සහජීවනය ශක්තිමත් කරයි."),
    q("රටේ සංවර්ධනයට බාධාවක් වන 'දක්ෂයන් රට හැර යාම' (Brain Drain) අවම කර ගැනීමට රජය ගත යුතු ප්‍රධාන පියවර කුමක්ද?", "රට තුළ ආර්ථික ස්ථාවරත්වය, කුසලතාවයට සරිලන වැටුප්, පර්යේෂණ පහසුකම් හා යහපාලනය ඇති කිරීම", "සියලු විශ්වවිද්‍යාල වසා දැමීම", "විදේශ ගමන් බලපත්‍ර තහනම් කිරීම", "වෛද්‍යවරුන් හා ඉංජිනේරුවන් පුහුණු නොකිරීම", "උගත් වෘත්තිකයන් රට තුළ රඳවා ගැනීම තිරසාර ආර්ථික ප්‍රගතියට ඉතා තීරණාත්මකය."),
    q("වෙළඳපොළේදී පාරිභෝගිකයාට 'සේවා සැපයුම්කරුවෙකුගෙන්' (විදුලි කාර්මිකයා, බැංකුව හෝ රෝහල වැනි) අසාධාරණයක් වුවහොත් හිමි අයිතිය කුමක්ද?", "භාණ්ඩ සඳහා මෙන්ම සේවා දෝෂ සඳහාද පැමිණිලි කිරීමේ හා වන්දි ඉල්ලීමේ අයිතිය", "සේවා සඳහා කිසිදු නීතියක් අදාළ නොවීම", "රජයට පමණක් පැමිණිලි කළ නොහැකි වීම", "සේවා ගාස්තු දෙගුණ කර ගෙවීම", "පාරිභෝගික අධිකාරි පනත භාණ්ඩ මෙන්ම සේවාවන්ද ආවරණය කරයි."),
    q("පරිසරය හා මානව සෞඛ්‍යය රැකගැනීම සඳහා 'කර්මාන්තශාලා ශබ්ද දූෂණය හා වායු දූෂණය' පාලනය කළ යුත්තේ කුමන නීතිමය සීමාවලට අනුවද?", "ජාතික පාරිසරික පනත යටතේ මධ්‍යම පරිසර අධිකාරිය නියම කර ඇති ඩෙසිබල් හා විමෝචන ප්‍රමිතීන්ට අනුව", "කර්මාන්ත හිමිකරුගේ පෞද්ගලික කැමැත්තට අනුව", "කිසිදු සීමාවක් නොමැතිව", "පළාත් පාලන බදු අනුව පමණි", "රාත්‍රී කාලයේ ශබ්ද මට්ටම හා දුම් විමෝචනය සීමා කිරීමෙන් ජනාවාසවල සෞඛ්‍යය රැකගනී."),
    q("රටේ සංවර්ධනය සඳහා 'විද්‍යා හා තාක්ෂණ පර්යේෂණ' (R&D) ප්‍රවර්ධනය කිරීම වැදගත් වන්නේ ඇයි?", "නව නිෂ්පාදන, පිරිසිදු බලශක්ති හා ඉහළ ඵලදායී කෘෂිකාර්මික ක්‍රම බිහි කර තරගකාරීත්වය වැඩි කිරීමට", "සාම්ප්‍රදායික දැනුම සම්පූර්ණයෙන් විනාශ කිරීමට", "විදේශ ආනයන පමණක් වැඩි කිරීමට", "පාසල් විද්‍යාගාර වසා දැමීමට", "නවෝත්පාදන ආර්ථිකයක් ගොඩනැගීම සඳහා විශ්වවිද්‍යාල හා කර්මාන්ත අතර පර්යේෂණ සහයෝගීතාව අත්‍යවශ්‍යය."),
    q("තිරසාර සංවර්ධනයේදී 'ගෝලීය සහයෝගීතාව' (SDG 17 - Partnerships for the Goals) අත්‍යවශ්‍ය වන්නේ ඇයි?", "දේශගුණික විපර්යාස, දිළිඳුකම හා වසංගත වැනි ගැටලු තනි රටකට පමණක් විසඳිය නොහැකි බැවිනි", "රටවල් අතර වෙළඳාම සම්පූර්ණයෙන් නැවැත්වීමට", "දේශසීමා වසා දැමීමට", "තනිව යුද්ධ කිරීමට", "මූල්‍ය, තාක්ෂණ හා දැනුම බෙදාගැනීමෙන් ලෝකයේ සියලු රටවලට 2030 ඉලක්ක කරා යා හැක."),
    q("ශ්‍රී ලංකාවේ 'ආර්ථික සංවර්ධනයේදී' ස්වාභාවික වරායන් හා භූගෝලීය පිහිටීම වැදගත් වන්නේ කෙසේද?", "නැගෙනහිර හා බටහිර ප්‍රධාන ජාත්‍යන්තර නාවික මාර්ගය මධ්‍යයේ පිහිටීමෙන් නාවික හා සැපයුම් මධ්‍යස්ථානයක් වීමට හැකි වීමෙන්", "ගුවන් ගමන් සම්පූර්ණයෙන් නතර වීමෙන්", "විදේශ නැව්වලට ඇතුළු වීම තහනම් කිරීමෙන්", "ධීවර කර්මාන්තය අඩු කිරීමෙන්", "කොළඹ, ත්‍රිකුණාමලය හා හම්බන්තොට වරායන් සේවා ආර්ථිකයට විශාල විභවයක් සපයයි."),
    q("වෙළඳපොළේදී 'මිල උච්චාවචනය' අධික කෘෂිකාර්මික බෝග සඳහා ගබඩා හා ශීතාගාර පහසුකම් දියුණු කිරීම වැදගත් වන්නේ ඇයි?", "අස්වනු නෙළන කාලයේ අතිරික්තය නාස්ති වීම වළක්වා අවාරයේදී සාධාරණ මිලකට සැපයීමට", "ගොවීන්ට අස්වැන්න විසි කිරීමට සැලැස්වීමට", "ආනයන බදු වැඩි කිරීමට", "පාරිභෝගිකයාට හිඟයක් ඇති කිරීමට", "පසු-අස්වනු තාක්ෂණය (Post-harvest Technology) දියුණු කිරීමෙන් ගොවියාත් පාරිභෝගිකයාත් දෙදෙනාම රැකේ."),
    q("සෑම පුරවැසියෙකුම 'බදු ගෙවීම' රටේ සුබසාධන සේවා අඛණ්ඩව පවත්වාගෙන යාමට උපකාරී වන්නේ කෙසේද?", "නිදහස් අධ්‍යාපනය, නොමිලේ සෞඛ්‍යය, රෝහල්, පොලිසිය හා මාර්ග නඩත්තුවට අවශ්‍ය මුදල් සැපයීමෙන්", "රාජ්‍ය සේවක වැටුප් නැවැත්වීමෙන්", "රෝහල් පෞද්ගලීකරණය කිරීමෙන්", "විදේශ ණය බර වැඩි කිරීමෙන්", "රාජ්‍ය ආදායමෙන් පොදු සේවා ක්‍රියාත්මක වන බැවින් අවංකව බදු ගෙවීම උසස් පුරවැසි යුතුකමකි."),
    q("බහුසංස්කෘතික සමාජයක 'මාධ්‍ය විසින් සංස්කෘතික විවිධත්වය' නිරූපණය කළ යුත්තේ කෙසේද?", "සියලු ජන කොටස්වල කලා, භාෂා හා ජීවන අත්දැකීම් සමාන ගෞරවයෙන් හා අගතියකින් තොරව ඉදිරිපත් කිරීමෙන්", "සුළුතර ප්‍රජාවන් සමච්චලයට ලක් කිරීමෙන්", "වෛරී පුවත් නිර්මාණය කිරීමෙන්", "එක් භාෂාවක වැඩසටහන් පමණක් ප්‍රචාරය කිරීමෙන්", "නිවැරදි මාධ්‍ය නියෝජනය සමාජ සංහිඳියාව හා ජාතික සමගිය ශක්තිමත් කරයි."),
    q("පරිසරයට හා සමාජයට හානි කරන 'නීති විරෝධී ඉඩම් ගොඩකිරීම් හා වන විනාශය' වැළැක්වීමේදී පුරවැසියන්ට කළ හැකි දේ කුමක්ද?", "තොරතුරු දැනගැනීමේ අයිතිය භාවිත කර ප්‍රශ්න කිරීම හා වන සංරක්ෂණ/පරිසර ආයතනවලට පැමිණිලි කිරීම", "නිහඬව අනුබල දීම", "තමනුත් වගුරු බිම් ගොඩකිරීම", "කසළ වනාන්තරවලට දැමීම", "සක්‍රීය පුරවැසි අධීක්ෂණය පාරිසරික අපරාධ නැවැත්වීමේ ප්‍රබලම ශක්තියයි."),
    q("ශ්‍රී ලංකාවේ 'සහනාධාර ක්‍රම' ලබාදීමේදී පුද්ගලයා වැඩ කිරීමෙන් අධෛර්යමත් නොවී ආර්ථිකයට දායක වන ලෙස සකස් කළ යුත්තේ ඇයි?", "සුබසාධනය තාවකාලික අත්වැලක් කර දී පවුල් ස්වයංපෝෂිත හා ශ්‍රම බලකායට සක්‍රීය කර ගැනීමට", "සෑම අයෙකුම සදාකාලිකව ආධාර මත යැපීමට සැලැස්වීමට", "නිෂ්පාදන කටයුතු නැවැත්වීමට", "අයවැය හිඟය වැඩි කිරීමට", "සැබෑ සමාජ ආරක්ෂණය දුප්පතුන් දිළිඳුකමින් සදාකාලිකව මුදවා ස්වාධීන කිරීම ඉලක්ක කරගනී."),
    q("තිරසාර සංවර්ධනය සඳහා 'කාන්තාවන් ආර්ථික ක්‍රියාවලියට වැඩි වශයෙන් සහභාගි කර ගැනීම' (Women's Economic Participation) වැදගත් වන්නේ ඇයි?", "රටේ ශ්‍රම බලකාය පුළුල් වී පවුල් ආදායම, දරුවන්ගේ පෝෂණය හා ජාතික නිෂ්පාදනය ඉහළ යන බැවිනි", "කාන්තාවන්ට අධ්‍යාපනය නැවැත්වීමට", "ගෘහ ආර්ථිකය දුර්වල කිරීමට", "රැකියා අවස්ථා අඩු කිරීමට", "සුරක්ෂිත ප්‍රවාහනය හා ළමා සුරැකුම් පහසුකම් සැලසීමෙන් කාන්තා ශ්‍රම දායකත්වය ඉහළ නැංවිය හැක."),
    q("වෙළඳපොළ ආර්ථිකයක 'පාරිභෝගික ආරක්ෂණ සංගම්' (Consumer Associations) පිහිටුවා ගැනීමෙන් ජනතාවට ලැබෙන ශක්තිය කුමක්ද?", "සාමූහිකව හඬ නඟා අසාධාරණ මිල වැඩිවීම් හා බාල භාණ්ඩවලට එරෙහිව පියවර ගැනීමට හැකි වීම", "වෙළඳසැල්වලින් භාණ්ඩ පැහැර ගැනීමට", "රජයේ බදු ගෙවීම නැවැත්වීමට", "නීති විරෝධී වෙළඳාම් කිරීමට", "සංවිධානාත්මක පාරිභෝගික ප්‍රජාවකට වෙළඳපොළ වගවීම ඉහළ නැංවිය හැකිය."),
    q("ශ්‍රී ලංකාවේ 'සියලු ප්‍රජාවන්ට පිළිගත හැකි තිරසාර සංවර්ධනයක්' යනු කුමක්ද?", "පරිසරය රැකෙන, දිළිඳු බව දුරු වන හා සෑම ජන කොටසකටම සාධාරණ අවස්ථා හිමිවන ප්‍රගතිය", "පරිසරය විනාශ කර නගර පමණක් ගොඩනැගීම", "එක් කලාපයක් පමණක් දියුණු කිරීම", "අධ්‍යාපනය හා සෞඛ්‍යය කප්පාදු කිරීම", "ආර්ථික, සමාජීය, සංස්කෘතික හා පාරිසරික සමබරතාව රැකගත් සංවර්ධනය දීර්ඝකාලීන සාමයද උදා කරයි."),
    q("රටේ පුරවැසියන් වශයෙන් ආපදා, ආර්ථික අභියෝග හා සංස්කෘතික විවිධත්වය හමුවේ ගොඩනගා ගත යුතු ප්‍රධාන ගුණාංගය කුමක්ද?", "සමාජ වගකීම, සහයෝගීතාව, අරපිරිමැස්ම හා තිරසාර ජීවන රටාව", "නාස්තිය හා ආත්මාර්ථකාමීත්වය", "පාරිසරික නොසැලකිල්ල", "ජාතික සමගිය බිඳ දැමීම", "සෑම පුරවැසියෙකුගේම වගකීම්සහගත ජීවන රටාව ශක්තිමත්, සෞභාග්‍යමත් හා සාමකාමී දේශයක් බිහි කරයි.")
  )
}

